head.b:skin:
/*----------------------------------------------- 
Blogger Template Style
Name	: Blogspot AI SEO Landing Framework v4.8 Author Entity Refinement
URL	    : https://www.blogspotlandingpage.com
author  : Arif Stiawan
----------------------------------------------- */
/* Variable definitions
====================
<Group description="Pengaturan Body" selector=".konten">
<Variable name="content.width" description="Lebar Halaman" type="length" default="1200px" min="480px" max="1920px" value="1200px"/>
<Variable name="body.background1" description="Warna Background Atas Kiri" type="color" default="#f59c00" value="#fc058c"/>
<Variable name="body.background2" description="Warna Background Atas Kanan" type="color" default="#ff3000" value="#ff6909"/>
<Variable name="wrapper.background" description="Warna Background Utama" type="color" default="#f3f6fd" value="#f3f6fd"/>
<Variable name="body.sp" description="Posisi Bayangan" type="length" default="10px" min="0" max="40px" value="1px"/>
<Variable name="body.sl" description="Blur Bayangan" type="length" default="3px" min="0" max="40px" value="3px"/>
<Variable name="body.sc" description="Warna Bayangan" type="color" default="#dae5fe" value="#dae5fe"/>
<Variable name="body.sb" description="Besar Bayangan" type="length" default="1px" min="0" max="100px" value="1px"/>
</Group>
<Group description="Pengaturan Link" selector="a">
<Variable name="a.link" description="Warna Link" type="color" default="#0047b2" value="#0047b2"/>
<Variable name="a.hover" description="Wana Link Hover" type="color" default="#0088ff" value="#0088ff"/>
</Group>
<Group description="Pengaturan Menu Melayang" selector=".headermenu">
<Variable name="nav.bg" description="Background" type="color" default="#222222" value="transparent"/>
<Variable name="nav.hover" description="Background Hover" type="color" default="#000000" value="transparent"/>
<Variable name="nav.color" description="Wana Teks" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="scroll.nav.bg" description="Background Scroll" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="scroll.nav.hover" description="Background Hover  Scroll" type="color" default="#e7e7e7" value="#e7e7e7"/>
<Variable name="scroll.nav.color" description="Wana Teks  Scroll" type="color" default="#222222" value="#222222"/>
</Group>
<Group description="Pengaturan Post" selector="body">
<Variable name="body.font" description="Font" type="font" default="small Arial,Geneva,sans-serif" value="normal normal 16px Poppins"/>
<Variable name="post.color" description="Warna Teks" type="color" default="#222222" value="#292929"/>
<Variable name="post.background" description="Warna Background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="post.radius" description="Border Radius" type="length" default="20px" min="0" max="100px" value="8px"/>
</Group>
<Group description="Pengaturan Sidebar" selector="#right-bar">
<Variable name="side.font" description="Ukuran Judul" type="length" default="18px" min="0" max="100px" value="18px"/>
<Variable name="side.color" description="Warna Judul" type="color" default="#292929" value="#000000"/>
<Variable name="side.background" description="Warna Background" type="color" default="#ffffff" value="#FFFFFF"/>
<Variable name="side.radius" description="Border Radius" type="length" default="8px" min="0" max="100px" value="6px"/>
<Variable name="side.content" description="Warna Teks" type="color" default="#222222" value="#292929"/>
<Variable name="side.hover" description="Warna Teks hover" type="color" default="#00a2ff" value="#0864ee"/>
</Group>
<Group description="Pengaturan Footer" selector="#copyright">
<Variable name="copyright.color" description="Warna Teks Copyright" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="copyright.background" description="Warna Background Copyright" type="color" default="#000000" value="#0864ee"/>
<Variable name="bg.totop" description="Warna Back to Top" type="color" default="#2679ec" value="#000000"/>
</Group>
<Group description="Pengaturan Mode Gelap" selector=".Night">
<Variable name="night.bg" description="Warna Background Atas" type="color" default="#000000" value="#000000"/>
<Variable name="night.bg1" description="Warna Background Utama" type="color" default="#090f14" value="#090f14"/>
<Variable name="night.bg2" description="Warna Background Postingan" type="color" default="#131c25" value="#131c25"/>
<Variable name="night.color" description="Warna Teks" type="color" default="#d5d9dd" value="#d5d9dd"/>
<Variable name="night.a" description="Warna Link" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="night.hover" description="Warna Link Hover" type="color" default="#ffba00" value="#ffba00"/>
</Group>
*/
#layout:before{content:'Blogspot Landing Page Builder 3.2.1';position:absolute;top:20px;left:5px;right:5px;height:1px;text-align:center}
#layout #outer-wrapper{width:100%;}
#layout #left-side{width:70%;float:left;overflow:hidden;}
#layout #right-bar{overflow:hidden;}
#layout #right-bar .widget-content{margin-bottom:0}
#layout #footer-wrapper{overflow:hidden;}
.search-result img{margin-bottom:10px;border-radius:$(post.radius) $(post.radius) 0 0}
.post-body img{border-radius:$(side.radius) $(side.radius) 0 0}
a{color:$(a.link);transition:all .5s ease 50ms; text-decoration:none}
a:hover{color:$(a.hover);text-decoration:none; transition:all .5s ease 50ms;}
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, [tabindex]:focus-visible {outline: 3px solid #155eef !important; outline-offset: 3px !important;}
.fa,.fas,.far,.fal,.fab {-moz-osx-font-smoothing: grayscale;-webkit-font-smoothing: antialiased;display: inline-block;font-style: normal;font-variant: normal;text-rendering: auto;line-height: 1;}
.fa-ul {list-style-type: none;margin-left: 1.5em;padding-left: 0;}
.fa-ul > li {position: relative;}
.fa-li {left: -2em;position: absolute;text-align: center;width: 2em;line-height: inherit;}
.Night a{color:$(night.a)!important; transition:all .5s ease 50ms; text-decoration:none}
.Night a:hover{color:$(night.hover)!important;transition:all .5s ease 50ms; text-decoration:none}
#right-bar h3.title{padding:0; margin:15px 0 10px 0;font-size:$(side.font); font-weight:900;color:$(side.color)}
#right-bar .LinkList .widget-content,#right-bar .PopularPosts .post-content,#right-bar  .Label li, #ArchiveList,#right-bar .TextList .widget-content li{background:$(side.background); color:$(side.content); box-shadow:$(body.sp) $(body.sp) $(body.sl) $(body.sb) $(body.sc); transition: all .3s ease-out;}
#right-bar .LinkList .widget-content a, .PopularPosts .post-content a,#right-bar  .Label li a, #ArchiveList a{color:$(side.content)}
#right-bar .LinkList .widget-content a:hover,#right-bar .PopularPosts .post-content a:hover,#right-bar .Label li a:hover, #ArchiveList a:hover,#right-bar .HTML .widget-content a:hover{color:$(side.hover)}
#right-bar .widget-content{margin-bottom:30px}
#right-bar .HTML .widget-content{background-color:$(side.background); color:$(side.content); box-shadow:$(body.sp) $(body.sp) $(body.sl) $(body.sb) $(body.sc); transition: all .3s ease-out;}
#right-bar .tagpost_thumb{box-shadow:$(body.sp) $(body.sp) $(body.sl) $(body.sb) $(body.sc); transition: all .3s ease-out;}
ul#related-summary li img{border-radius:$(side.radius);}
body{font:$(body.font); background:linear-gradient(to top right, $(body.background1), $(body.background2)); color:$(post.color)}
#wrapper{;background: $(wrapper.background)}
#left-side,.post-outer{background: $(post.background); border-radius:$(post.radius); box-shadow:$(body.sp) $(body.sp) $(body.sl) $(body.sb) $(body.sc); transition: all .3s ease-out;}
.BlogSearch .widget-content{padding:7px 0 0 7px;border-radius:$(side.radius); background:$(side.background); box-shadow:$(body.sp) $(body.sp) $(body.sl) $(body.sb) $(body.sc);}
.Night .BlogSearch .widget-content{background:$(night.bg2); padding:7px 0 0 7px; box-shadow:none}
.search-input{width:calc(100% - 45px); float:left; background:$(post.background); border: 0;border-radius:$(side.radius);}
.search-input input{margin-left: 0px; width:100%; float:left; border-radius:$(side.radius); background:$(post.background); border: 1px solid #f1f3f6; font-size: 14px; padding:3px 5px 3px 15px; letter-spacing:1px; box-shadow:0 0 2px 0 #f1f3f6 inset;}
.Night .search-input input,.Night .search-input input:focus{background:$(night.bg2); color:$(night.color)}
.search-input input:focus {background:$(side.background); border: 0 solid #b1b1b1; border-radius:$(side.radius); width: 100%; box-shadow:0 2px 8px rgba(0,0,0,0.2);}
.search-action {overflow:hidden;background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiXqaxI94Qvbj2x3MhrhbEGd-5tFZ1gPKBEIs2V0uVC6gcK0JL7lfeu8sXvwHt2xBNDnbfZ66klvMLJ6IDDEuBEb4UcSpWYRc4D5ahDKO_YcFVNIsQqG1eXfTTMgfVinrt5jxvGsIdqI_l_haFEWtT1Gk0054sbYcacsOzLKW6L3d5WjmshOrFQc9_5/s1600/cari.png) no-repeat; margin-left: 2px; margin-top:-3px; border-width: 0px; width: 43px; height: 45px; text-indent:0px; font-size:1px; overflow:hidden;}
.Night .search-action{background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjYxdPSajj7Xyz09wFtEq4tXqnD1x2SqnvX0QEOSG_MaWeDP2ka0kRsDqwlnt8iukjfJ54ljLraS2iQNgWtoVKYZzr52Y3Z6QlpcxNfCh3m9sRwIpqBu5mEh0Dy2cglDLxr-FrGiKGUo3M_8iF1qy90bsfxcX9qxt0NpSbqSJG6t9hrO4pNiygd7G5p/s1600/cari-putih.png) no-repeat;}
.PopularPosts .item-snippet {font-size: 14px; line-height:1.2em}
.PopularPosts .post-content{padding:15px 8px 12px 15px; background:$(side.background); margin-bottom:15px; border-radius:$(side.radius); word-wrap:break-word; display:flex; display:-webkit-flex;  flex-wrap:wrap; -webkit-flex-wrap:wrap; -ms-flex-wrap:wrap; justify-content:space-between; align-items:center;}
.PopularPosts .post-content h3{font:$(body.font); margin:0;font-weight:400; width:calc(100% - 80px); text-align:left; padding:0; margin:0; line-height:normal;}
.PopularPosts .post-content h3.post-title a{display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden;}
.PopularPosts .post-content .item-thumbnail {overflow:hidden;}
.PopularPosts .post-content .item-thumbnail img{margin-right:0; padding-right:0; object-fit:cover; border-radius:$(side.radius);}
.Label ul {margin-left:-37px;}
.Label li {display:inline-block; list-style:none; margin:0px 5px 12px 0px; padding:4px 12px; width:auto; font:$(body.font); border-radius:$(side.radius);}
.FeaturedPost h3 {font-size: 18px; line-height:1.5em; margin-top:-10px}
.FeaturedPost .post-snippet {font-size: 15px; line-height:1.5em; float:left; height:72px; max-height:72px; overflow:hidden; max-width:calc(100% - 75px)}
.FeaturedPost .item-thumbnail {float:right; overflow:hidden;}
.FeaturedPost{padding-bottom:20px; clear:both}
.status-msg-border{border-radius:$(post.radius);}
#right-bar .HTML .widget-content{border-radius:$(side.radius); padding:0; font:$(body.font)}
#right-bar .HTML img{border-radius:$(side.radius)}
#right-bar .HTML .title{ display: block; }
#right-bar .contact-form-widget{padding:0 10px; font:$(body.font);}
.BlogArchive li {font:$(body.font);}
#ArchiveList {overflow:auto; width:auto; max-height:300px; border-radius:$(side.radius); padding:20px; margin-top:0;}
#ArchiveList .post-count{display:none}
.jump-link a{background:$(a.link); padding:8px 13px; border-radius:$(post.radius); color:$(wrapper.background); font-size:13px}
.jump-link a:hover{background:$(a.hover);}
.Night .jump-link a{background:$(night.a); color:$(night.bg1)!important; font-size:13px}
.Night .jump-link a:hover{background:$(night.hover);}
.LinkList .widget-content {padding:15px; background:#ffffff; border-radius:$(side.radius); margin-top:0}
.LinkList .widget-content li{list-style:none; margin:3px 0 5px -35px; font:$(body.font); padding-bottom:10px}
.TextList .widget-content li{list-style:none; margin:5px 0 15px -40px; background:$(side.background); padding:8px 10px 8px 15px; border-radius:$(side.radius); font:$(body.font); box-shadow:$(body.sp) $(body.sp) $(body.sl) $(body.sb) $(body.sc); transition: all .5s ease-out;}
.TextList .widget-content li:hover{transform:translateX(10px); transition:all .5s ease-out;z-index:-1}
.Night #left-side,.Night #right-bar .LinkList .widget-content, .Night #right-bar .PopularPosts .post-content, .Night #right-bar .Label li, .Night #ArchiveList,.Night #right-bar .HTML .widget-content,.Night #right-bar .TextList .widget-content li,.Night #right-bar .tagpost_thumb{box-shadow:none;}
.TextList .widget-content li:before{content: ""; font-style: normal; font-weight: normal;}
#feed-container li{border-radius:$(post.radius); background:$(post.background)}
#feed-container li img{border-radius:$(side.radius) $(side.radius) 0 0;}
.comments-content {overflow:auto; width:auto; max-height:400px; padding:3px; border-radius:$(side.radius)}
.blogger-comment-from-post,.blogger-iframe-colorize{border-radius:$(side.radius)}
.comments h4 {font-size: 15px;}
.comments .avatar-image-container {max-height: 50px;width: 50px;}
.comments .avatar-image-container img {border-radius: 50px; border:3px solid #f5f5f5; width: 40px;height: 40px; margin-right: 50px; max-width: 50px;}
.comments .comment-block {border: 1px solid transparent;background: transparent; padding: 5px; font-size: 12px; border-radius: 6px; margin-left: 50px;}
.comments .comment-block::after {content: &#39; &#39;; position: absolute; width: 0;height: 0; left: -14px;top: 16px; border: 7px solid; border-color: transparent transparent transparent transparent;}
.comments .comment-block::before {content: &#39; &#39;; position: absolute; width: 0;height: 0;top: 15px; left: -16px; border: 8px solid; border-color: transparent transparent transparent transparent;}
.comments .comment-header,.comments .comments-content .comment-thread,.comments .continue a {font-size: 12px;}
.comments .comment-header {color: #21b6fc;padding: 3px;border-radius: 4px;line-height:1.3em;}
.comments .comment-content {font-size: 13px;padding: 3px;line-height:1.4em;}
.comments .comments-content .comment-content {margin-bottom: 10px;}
.comments .comments-content .datetime{display: none;}
.comments .comments-content .user {font-style:normal;font-weight:normal;font-size: 15px;}
.comments .comment .comment-actions a {margin-top: 30px;background: transparent;color: grey;padding: 3px;margin: 3px;border-radius: 4px;border:1px solid #dadada}
.comments .continue a {display:inline;background: transparent;color: grey;padding: 3px;text-align: center;font-weight: normal;border-radius: 4px;border:1px solid #dadada}
.comments .continue a:hover {text-decoration: none;background: transparent;border:1px solid #dadada}
.comments .comment .comment-actions a:hover{text-decoration: none;background: transparent;border:1px solid #dadada}
#copyright{background:$(copyright.background);padding:20px 10px;text-align:center;font:$(body.font);color:$(copyright.color)}
#copyright a{color:$(copyright.color)}#copyright a:hover{color:$(a.hover)}
.Night #copyright{background:$(night.bg2);color:$(night.color)}
.Night #copyright a{color:$(night.color)}#copyright a:hover{color:$(a.hover)}
.headermenu{position: fixed;top:0; left:0; right: 0;z-index: 1000;background:$(nav.bg);box-shadow:0 .5rem 1.5rem rgba(0,0,0,.1);display: flex;align-items: center;justify-content: space-between;padding:0 6%;font:$(body.font);line-height:2em;transition: all .3s ease-out;}
.headermenu.discroll{background:$(scroll.nav.bg);}
.headermenu .logos{margin: 0;font-size: 2.5rem;color:$(nav.color);font-weight: bolder;}
.headermenu.discroll .logos{color:$(scroll.nav.color)}
.headermenu .logos img{width:220px;height:auto;max-width:100%;max-height:none;}
.headermenu .navbar{margin:0;transition: all .3s ease-out;padding:1.5rem 0rem 1.5rem 2rem;}
.headermenu .navbar a{font-size: 1.6rem;color: $(nav.color);padding:2rem 1.5rem;transition: all .3s ease-out;}
.headermenu.discroll .navbar a{color: $(scroll.nav.color)}
.headermenu .navbar a:hover{color:$(nav.color);background: $(nav.hover);transition: all .3s ease-out;}
.headermenu.discroll .navbar a:hover{color:$(scroll.nav.color);background: $(scroll.nav.hover)}
#menu-btn{cursor: pointer;font-size: 2.5rem;padding:.3rem .7rem;border-radius: .5rem;color: $(nav.color);background: rgba(0,0,0,.3);display: none;transition: all .3s ease-out;}
#menu-btn:hover{color: $(nav.color);background: rgba(0,0,0,.3);transition: all .3s ease-out;}
.headermenu.discroll #menu-btn{color: $(scroll.nav.color);background: $(scroll.nav.hover);transition: all .3s ease-out;}
.headermenu.discroll #menu-btn:hover{color: $(scroll.nav.color);background: $(scroll.nav.hover);transition: all .3s ease-out;}
.headermenu .dropbtn {background:$(nav.bg);color:$(nav.color);cursor:pointer}
.headermenu.discroll .dropbtn {background:$(scroll.nav.bg);color:$(scroll.nav.color)}
.headermenu .dropdown {position: relative;display: inline-block;}
.headermenu .dropdown-content {display: none;position: absolute;background:$(scroll.nav.bg);min-width: 26rem;box-shadow: 0px 8px 16px 0px rgba(0,0,0,0.2);z-index: 1;border-radius: .5rem;color:$(scroll.nav.color);max-height: 50vh;overflow-y: auto;scrollbar-width: thin;}
.headermenu.discroll .dropdown-content {background:$(scroll.nav.bg);}
.headermenu .dropdown-content a{text-decoration: none;display: block;background:transparent;color:$(scroll.nav.color)}
.headermenu .navbar .dropdown-content a{padding:1rem 1.5rem}
.headermenu .dropdown-content a:hover {background: $(scroll.nav.hover);border-radius: .5rem;color:$(scroll.nav.color)}
.headermenu.discroll .dropdown-content a:hover {background: $(scroll.nav.hover)}
.headermenu .dropdown:hover .dropdown-content {display: block;border-radius: .5rem;}
.headermenu .dropdown:hover .dropbtn {background:$(nav.bg)}  
.headermenu.discroll .dropdown:hover .dropbtn {background:$(scroll.nav.hover)}
.Night .headermenu .dropbtn {background:$(night.bg2)}
.Night .headermenu .dropdown:hover .dropbtn,.Night .headermenu.discroll .dropdown:hover .dropbtn {background:$(night.bg1)}
.Night .headermenu,.Night .dropdown-content{background:$(night.bg2);transition: all .3s ease-out;}
.Night .headermenu .logos,.Night .headermenu .navbar a{color:$(night.color)}
.Night .headermenu .navbar a:hover{color:$(night.color);background: $(night.bg1);transition: all .3s ease-out;}
.Night #menu-btn{color: $(night.bg2);background: $(night.color);transition: all .3s ease-out;}
.Night #menu-btn:hover{color: $(night.bg1);background: $(night.color);transition: all .3s ease-out;}
.Night .headermenu.discroll .dropdown-content {background:$(night.bg2);}
.Night .headermenu.discroll .dropbtn {background:$(night.bg2);color:$(night.color)}
.Night .headermenu.discroll .dropbtn:hover {background:$(night.bg2)}
.post-body pre{background-color:$(post.color);border:none;border-left:5px solid $(a.hover);padding:15px 10px;margin:1em auto;color:$(post.background);}
.Night .post-body pre{background-color:$(night.bg1);border-left:5px solid #000000;padding:15px 10px;margin:1em auto;color:$(night.color);}
.Night #related-post h4{color: $(night.color)}
#outer-wrapper{width:$(content.width);}
h1.post-title.entry-title,h1.post-title.entry-title a {text-align:left;font-weight:600;color:$(post.color)}
h1.post-title.entry-title a:hover{color:$(a.hover);text-decoration:none}
h1 {font-size:32px;line-height:1.3em;padding:5px 0;margin:5px 0}
h2 {font-size:32px;line-height:1.3em;padding:5px 0;margin:5px 0}
h3 {font-size:32px;line-height:1.3em;padding:5px 0;margin:5px 0}
h4 {font-size:26px;line-height:1.3em;padding:5px 0;margin:5px 0}
h5 {font-size:22px;padding:5px 0;line-height:1.3em;margin:5px 0}
h6 {font-size:18px;padding:5px 0;line-height:1.3em;margin:5px 0}
.kol2,.kol-2,.kol-12{padding:0;float:left;width:calc(100% / 2);transition:all .5s ease 50ms;}
.kol3,.kol-3,.kol-13{padding:0;float:left;width:calc(100% / 3);transition:all .5s ease 50ms;}
.kol4,.kol-4,.kol-14,.kol14,.kolom-4{padding:0;float:left;width:calc(100% / 4);transition:all .5s ease 50ms;}
.kol5,.kol-5,.kol-15,.kol15{padding:0;float:left;width:calc(100% / 5);transition:all .5s ease 50ms;}
.kol6,.kol-6,.kol-16,.kol16{padding:0;float:left;width:calc(100% / 6);transition:all .5s ease 50ms;}
.kol23,.kol-23,.kol-123{padding-bottom:0;float:left;width:calc((100% * 2) / 3);transition:all .5s ease 50ms;}
.kol-60{padding:0;float:left;width:calc((100% / 10) * 6);transition:all 1s ease 50ms;}
.kol-40{padding:0;float:left;width:calc((100% / 10) * 4);transition:all 1s ease 50ms;}
.konten {margin:0px auto;padding-right:0;padding-left:0;max-width:$(content.width)}
.group:after {content: "";display: table;clear: both;}
.konten:after{content:"";display:table;clear:both}
.grid{display:flex;  display:-webkit-flex;  flex-wrap:wrap;  -webkit-flex-wrap:wrap;  -ms-flex-wrap:wrap;justify-content: center;}
.flip,.tukar{flex-direction: row-reverse}
.style1 {font-family:'Anton', sans-serif;line-height:1.4em}
.style2 {font-family:'Russo One', sans-serif;line-height:1.2em}
.style3 {font-family:'Archivo Black', sans-serif;line-height:1.2em}
.style4 {font-family:'Open Sans', sans-serif;line-height:1.4em}
.style5 {font-family:'Roboto', sans-serif;line-height:1.2em}
.style6 {font-family:'lato', sans-serif;line-height:1.2em}
.style7 {font-family:'Bangers', cursive;line-height:1.2em}
.style8 {font-family:'Viga', sans-serif;line-height:1.2em}
.style9 {font-family:'Oxygen', sans-serif;line-height:1.3em}
.style10 {font-family:'Kite One', sans-serif;line-height:1.4em}
.style11 {font-family:'Pattaya', sans-serif;line-height:1.2em}
.style12 {font-family:'Spectral', cursive;line-height:1.3em}
.style13 {font-family:'Allerta Stencil', sans-serif;line-height:1.2em}
.style14 {font-family:'Encode Sans Semi Expanded', sans-serif;line-height:1.3em}
.style15 {font-family:'Special Elite', cursive;line-height:1.3em}
.style16 {font-family:'Reem Kufi', sans-serif;line-height:1.2em}
.style17 {font-family:'Arima Madurai', cursive;line-height:1.3em}
.style18 {font-family:'Bubblegum Sans', cursive;line-height:1.2em}
.style19 {font-family:'Kelly Slab', cursive;line-height:1.2em}
.style20 {font-family:'Lekton', sans-serif; line-height:1.3em}
.style21 {font-family:'Oleo Script Swash Caps', cursive;line-height:1.2em}
.style22 {font-family:'Stardos Stencil', cursive;line-height:1.2em}
.style23 {font-family:'Kranky', cursive;line-height:1.2em}
.style24 {font-family:'Seaweed Script', cursive;line-height:1.2em}
.style25 {font-family:'Sail', cursive;line-height:1.2em}
