.sharepost {padding-top:10px}
.sharepost{overflow:hidden;text-align:left; margin-bottom:10px; margin-top:20px;font:$(body.font)}
.sharepost ul{margin-left:-44px; margin-top:5px}
.sharepost li{padding:0;list-style:none;margin:4px;text-align:center;}
.sharepost li a{width:35px;height:35px;display:block;border:0; border-radius:50%;line-height:2.05em;font-size:17px}
.sharepost li .twitter,.sharepost li .facebook,.sharepost li .telegram,.sharepost li .pinterest,.sharepost li .linkedin,.sharepost li .whatsapp{background-color:$(wrapper.background); color:$(post.color);}
.Night .sharepost li .twitter,.Night .sharepost li .facebook,.Night .sharepost li .telegram,.Night .sharepost li .pinterest,.Night .sharepost li .linkedin,.Night .sharepost li .whatsapp{background-color:$(night.bg1);color:$(night.color);}
.sharepost li a.twitter:hover{background-color:#000000;color:$(post.background);}
.sharepost li a.facebook:hover{background-color:#3b5998;color:$(post.background);}
.sharepost li a.telegram:hover{background-color:#33ccff;color:$(post.background);}
.sharepost li a.pinterest:hover{background-color:#cc2127;color:$(post.background);}
.sharepost li a.linkedin:hover{background-color:#0976b4;color:$(post.background);}
.sharepost li a.whatsapp:hover{background-color:green;color:$(post.background);}
.sharepost li{float:left;margin-right:0}
.sharepost li:last-child{margin-right:0}
.sharepost li .fa:before{margin-right:0}
.lembut{transition:all .5s ease 50ms;}
