.ContactForm,.post-icons{display:none}
#kontak-landing{margin:auto;max-width:640px}
#ContactForm1_contact-form-name,#ContactForm1_contact-form-email{height:35px;margin:5px auto;padding:12px 8px;background:#fff;color:#444;border:1px solid rgba(0,0,0,.14);box-shadow:inset 0 1px 1px rgba(0,0,0,0.075);border-radius:4px;width:100%;min-width:300px;transition:all 0.5s ease-out}
#ContactForm1_contact-form-email-message{width:100%;min-width:300px;height:100px;margin:5px 0;padding:12px 8px;background:#fff;color:#444;border:1px solid rgba(0,0,0,.14);box-shadow:inset 0 1px 1px rgba(0,0,0,0.075);border-radius:4px;resize:none;transition:all 0.5s ease-out}
#ContactForm1_contact-form-name:focus,#ContactForm1_contact-form-email:focus,#ContactForm1_contact-form-email-message:focus{outline:none;background:#fff;color:#444;border-color:#66afe9;box-shadow:inset 0 1px 1px rgba(0,0,0,.075),0 0 8px rgba(102,175,233,0.6)}
#ContactForm1_contact-form-submit{height:35px; float:left;background:$(a.link)!important;margin:auto;vertical-align:middle;cursor:pointer;padding:0 10px;font-size:14px;text-align:center;letter-spacing:.5px;border:0;width:100%;max-width:100px;border-radius:3px;color:#fff;font-weight:500;transition:all .8s ease}
#ContactForm1_contact-form-submit:hover{background:$(a.hover)!important;color:#fff;}
#ContactForm1_contact-form-error-message,#ContactForm1_contact-form-success-message{width:100%;margin-top:0} .contact-form-error-message-with-border{background:#f6f6f6;border:none;box-shadow:none;color:#444;padding:3px 0} .contact-form-success-message{background:#4fc3f7;border:none;box-shadow:none;color:#fff}img.contact-form-cross{line-height:40px;margin-left:5px} .post-body input{width:initial}
.easyslider-wrapper {width: auto;float: left;position: relative;padding-right: 1%;padding-top: 0px;}
.easyslider {overflow: hidden;position: relative;width: 960px;height: 380px;background: transparent;}
.image_reel {position: absolute;top: 0;left: 0;}
.image_reel img {float: left;width: 20%;height: 380px;}
.paging {background: none;position: absolute;bottom: 15px;right: 20px;padding:4px 0 2px;z-index: 100;display:none;}
.paging a {margin: 3px;background: #fff;width: 10px;height:10px;display: inline-block;border: none;outline:none;}
.paging a.active {background: #15E3FF;border: 1px solid #15E3FF;}
.paging a:hover {}
.easytitledes {width:70%;display: none;position: absolute;bottom: 20px;left: 20px;z-index: 101;background:#000A3F;background: rgba(2, 0, 51, 0.6);padding: 10px 15px;}
.easytitledes a {color: #54aefa;font: 20px sans-serif;text-transform: uppercase;font-weight: bold;}
.easytitledes a:hover {color:#2b89fd}
.easytitledes span {color: #fff;font: 16px Arial;}
.mengambang-1{animation: animation-1 .5s ease-out infinite;}
.mengambang-2{animation: animation-2 2s ease-out infinite;}
.mengambang-3{animation: animation-3 3s ease-out infinite;}
.mengambang-4{animation: animation-4 4s ease-out infinite;}
.maju-mundur{animation: maju-mundur 4s ease-out infinite;}
@keyframes maju-mundur {50% { transform: translate(25px, 0);}}
@keyframes animation-1 {50% { transform: translate(0, 10px);}}
@keyframes animation-2 {50% { transform: translate(0, 15px);}}
@keyframes animation-3 {50% { transform: translate(0, 20px);}}
@keyframes animation-4 {50% { transform: translate(0, 25px);}}
@keyframes blink{0%{color:red}100%{color:black}}
@-webkit-keyframes blink{0%{color:red}100%{color:black}}
.blink{-webkit-animation:blink 1s linear infinite;-moz-animation:blink 1s linear infinite;animation:blink 1s linear infinite}
.zoom-in,.img-zoom-in img,.icon-zoom-in i{-webkit-transition: all .5s ease;-moz-transition: all .5s ease;-o-transition: all .5s ease;-ms-transition: all .5s ease;transition: all .5s ease;} .zoom-in:hover,.img-zoom-in:hover img,.icon-zoom-in:hover i{-webkit-transform: scale(1.1, 1.1);-moz-transform: scale(1.1, 1.1);-ms-transform: scale(1.1, 1.1);-o-transform: scale(1.1, 1.2);transform: scale(1.1, 1.1);}
.bounce-out,.img-bounce-out img,.icon-bounce-out i{transition-duration:.5s} .bounce-out:active,.bounce-out:focus,.bounce-out:hover,.img-bounce-out:hover img,.icon-bounce-out:hover i,.img-bounce-out:focus img,.icon-bounce-out:focus i,.img-bounce-out:active img,.icon-bounce-out:active i{transform:scale(0.9);transition-timing-function:cubic-bezier(0.47,2.02,.31,-.36)}
.bounce-in,.img-bounce-in img,.icon-bounce-in i{transition-duration:.5s} .bounce-in:active,.bounce-in:focus,.bounce-in:hover,.img-bounce-in:hover img,.icon-bounce-in:hover i,.img-bounce-in:focus img,.icon-bounce-in:focus i,.img-bounce-in:active img,.icon-bounce-in:active i{transform:scale(1.1);transition-timing-function:cubic-bezier(0.47,2.02,.31,-.36)}
.berputar{-webkit-transition:all .2s ease-out;transition:all .2s ease-out} .berputar:hover {transform:rotate(360deg);transition:all .5s ease-out}
.serongkiri{transform:rotate(-5deg);}
.sorot-serongkiri{transition:all .5s ease-out;} .sorot-serongkiri:hover{transform:rotate(-5deg);transition:all .5s ease-out}
.serongkanan{transform:rotate(5deg);}
.sorot-serongkanan{transition:all .5s ease-out;} .sorot-serongkanan:hover{transform:rotate(5deg);transition:all .5s ease-out}
.keatas{transform:translateY(-20px);transition:all .5s ease-out}
.kebawah{transform:translateY(20px);transition:all .5s ease-out}
.kekiri{transform:translateX(-20px);transition:all .5s ease-out}
.kekanan{transform:translateX(20px);transition:all .5s ease-out}
.sorot-keatas,.sorot-kebawah,.sorot-kekiri,.sorot-kekanan{transition:all .5s ease-out}
.sorot-keatas:hover{transform:translateY(-10px);transition:all .5s ease-out}
.sorot-kebawah:hover{transform:translateY(10px);transition:all .5s ease-out}
.sorot-kekiri:hover{transform:translateX(-10px);transition:all .5s ease-out}
.sorot-kekanan:hover{transform:translateX(10px);transition:all .5s ease-out}
.getar{animation: getar .5s ease-out infinite;}
.sorot-getar:hover,.icon-getar:hover i,.img-getar:hover img{animation: getar .5s ease-out infinite;}
@keyframes getar {10% { transform: translate(3px, 0);}20% { transform: translate(-3px, 0);}30% { transform: translate(3px, 0);}40% { transform: translate(-3px, 0);}50% { transform: translate(3px, 0);}60% { transform: translate(0, 0);}}
.icon-flip i,.img-flip img{transform: rotateY(0deg);transition: all 0.5s ease-out;}
.icon-flip:hover i,.img-flip:hover img{transform: rotateY(360deg);transition: all 0.5s ease-out;}
.icon-berputar:hover i,.img-berputar:hover img{animation: icon-berputar 2s ease infinite}
@keyframes icon-berputar {0% { transform: rotate(0deg);} 100% { transform: rotate(360deg);}}
.icon-lompat:hover i,.img-lompat:hover img{animation: icon-lompat 1s ease infinite}
@keyframes icon-lompat {0% { transform: translateY(0);} 30% { transform: translateY(-10px);}50% { transform: translateY(0);}60% { transform: translateY(-5px);}}
.fitur{padding:40px 0} .fitur-atas{padding-top:40px} .lebar{padding:20px 0} .lebar-atas{padding-top:60px} .box{padding:15px} .padding{padding:30px} .pad{padding:5px} .gap{padding:0 15px} .mepet{padding:0px} .gaps{padding:15px 0} .boxs{padding:7.5px}
