.Night body{background:$(night.bg2);color:$(night.color)}
.Night .post-outer{background:$(night.bg2);box-shadow:none}
.Night #wrapper,.Night #outer-wrapper{background: $(night.bg1)!important}
.Night #left-side{background:$(night.bg2);}
.Night #right-bar h3.title{color:$(night.color);}
.Night .comments .comment-block {background:transparent;border: 1px solid transparent}
.Night .comments .comment-block::after {border-color: transparent transparent transparent transparent;}
.Night .comments .comment-block::before {border-color: transparent transparent transparent transparent;}
.Night body,.Night .breadcrumbs,.Night .post-body,.Night .date-header,.Night .sharepost,.Night .comments,.Night .modes{color:$(night.color)}
.Night {background:$(night.bg);}
.Night h1.post-title.entry-title,.Night h1.post-title.entry-title a{color:$(night.color)}
.Night #right-bar .LinkList .widget-content, .Night #right-bar .PopularPosts .post-content, .Night #right-bar .Label li, .Night #ArchiveList,.Night #right-bar .HTML .widget-content,.Night #right-bar .TextList .widget-content li{background:$(night.bg2);color:$(night.color)}
.Night a,.Night #right-bar .LinkList .widget-content a, .Night #right-bar .PopularPosts .post-content a, .Night #right-bar .Label li a, .Night #ArchiveList a,.Night #right-bar .HTML .widget-content a{color:$(night.color)}
.Night a:hover,.Night #right-bar .LinkList .widget-content a:hover, .Night #right-bar .PopularPosts .post-content a:hover, .Night #right-bar .Label li a:hover, .Night #ArchiveList a,.Night #right-bar .HTML .widget-content a:hover,.Night h1.post-title.entry-title a:hover{color:$(side.hover);}
#back-to-top{background:$(bg.totop);opacity:0.6;color:#ffffff;padding:10px 14px;font-size:20px;border-radius:50%;transition:all .5s ease 50ms;}
.back-to-top{position:fixed!important;position:absolute;bottom:30px;left:15px;z-index:99999;}
#back-to-top:hover {opacity:1;}
#right-bar .HTML img{text-align:center}
.switch input {display:none;}
.slider {position: absolute;cursor: pointer;top: 0;left: 0;right: 0;bottom: 0;-webkit-transition: .4s;transition: .4s;font-size:11px;line-height:0;}
input:checked + .slider:before {-webkit-transform: translateX(13px);-ms-transform: translateX(0px);transform: translateX(0px);}
.slider.round {border-radius: 14px;}
.slider.round:before {border-radius: 50%;}
.Night .slider.gelap {display:none}
.slider.terang {display:none}
.Night .slider.terang {display:block}
.switch {position: relative;display: inline-block;width: 19px;height: 19px;top:7px}
.slider {color:#ffffff;background:rgba(0,0,0,0.3)}
.Night .slider {background:rgba(255,255,255,0.3)}
.slider:before {background-color: $(a.hover);padding:4px}
.Night .slider:before {background-color: $(night.hover)}
.headermenu.discroll .slider{color:(scroll.nav.color)!important}
.Night .footer{background:$(night.bg2);color:$(night.color);transition: all .3s ease-out;}
.Night .teks-malam{color:$(night.color);transition: all .3s ease-out;}
.Night .btn-malam:hover{background:$(night.bg1);color:$(night.color)!important;transition: all .3s ease-out;}
.Night .bg-malam{background:#000000;transition: all .3s ease-out;}
.Night .bg-malam1{background:$(night.bg1);color:$(night.color);transition: all .3s ease-out;}
.Night .bg-malam2{background:$(night.bg2);color:$(night.color);transition: all .3s ease-out;}
