iframe.skiptranslate{border-left:none!important;border-top:none!important;border-bottom:none!important;border-right:none!important;border:none;box-shadow:none}
.goog-te-gadget-simple{background-color:transparent!important;background:url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEh-dRm7I_6qCwSRcJVCeArnQlcLuqNbTVq7_SqHQwCRxCZ_lElgPSZ3LtTjOnImvTjOG6bGZxbk9MpWnCrTAmCf-nagEwORQzSRHqiu8RMsHpp3pAKWr0p8JfWGFKMZoa-n5aeteTfocxArsTAKxDebqiv_3y6yltLKmQsGColSko5Id_ODdCNrUhywd_3D/s1600/translate.png) center / 12px no-repeat;-webkit-transition:all .2s ease;transition:all .2s ease;background-size: 20px 20px;display:inline-block;font-weight:400;line-height: 1.8;padding:0 6px;text-align:center;white-space:nowrap;vertical-align: middle;-ms-touch-action: manipulation;touch-action:manipulation;cursor:pointer;-webkit-user-select: none;-moz-user-select:none;-ms-user-select:none;user-select:none;border-left:none!important;border-top:none!important;border-bottom:none!important;border-right:none!important;border-radius: 4px}
body{top:0px!important;margin: 0px;}
@media (min-width:1600px){.headermenu{padding:0 13%;transition: all .3s ease-out;} .menu-switch{padding-right:14%;} #translateMenu{padding-right:8%;}}
@media (min-width:1920px){.headermenu{padding:0 19%;transition: all .3s ease-out;} .menu-switch{padding-right:20%;} #translateMenu{padding-right:14%;}}
@media (max-width:$(content.width)){.headermenu{padding:0 2%;transition: all .3s ease-out;padding-right:40px} .menu-switch{padding-right:80px}}
@media (max-width:991px){
#translateMenu{top:14px; right:calc(2% + 50px);}
.menu-switch{top:8px; right:calc(2% + 52px);padding-right:0}
#menu-btn{display: initial;}
.headermenu{padding:.5rem 2%;transition: all .3s ease-out;}
.headermenu .navbar{position: absolute;top:110%; right: 1.5rem;background:$(nav.bg);box-shadow: 0 .5rem 1.5rem rgba(0,0,0,.1);border:.1rem solid rgba(0,0,0,.1);border-radius: .5rem;width: 28rem;transform: scale(0);transform-origin: top right;opacity: 0;margin-top: 0.5rem;padding:0;transition: all .3s ease-out;}
.headermenu .dropdown {width:100%}
.headermenu .dropdown-content {position: relative;margin-left:15px;box-shadow: 0px 8px 16px 0px rgba(0,0,0,0)}
.headermenu .dropdown:hover .dropbtn {background:$(scroll.nav.hover)}  
.headermenu.discroll .navbar{background:$(scroll.nav.bg)}
.headermenu .navbar.active{transform: scale(1);opacity: 1;transition: all .3s ease-out;background:$(scroll.nav.bg);}
.Night .headermenu .navbar.active,.Night .headermenu .navbar a{background:$(night.bg2)}
.headermenu .navbar a{font-size: 1.5rem;display: block;padding:.7rem 1.2rem;margin: 0;border-radius: .5rem;transition: all .3s ease-out;background:$(scroll.nav.bg);color:$(scroll.nav.color)}
.headermenu .navbar a:hover{background:$(scroll.nav.hover);color:$(scroll.nav.color)}
.headermenu .logos{margin:0;font-size: 2.1rem;}
.headermenu .logos img{width:175px;height:auto;max-width:100%;max-height:none;}
.dropdown:hover .dropbtn{width: 28rem}
.Night .headermenu .navbar{background:$(night.bg2);transition: all .3s ease-out;}
}
@media only screen and (min-width: 481px){
.teks{overflow:hidden;}
}
/* v4.6 ACCESSIBILITY ENHANCEMENTS */
.btn-hijautua {background-color:#087a27; border-color:#087a27; color:#fff;}
.btn-hijautua:hover, .btn-hijautua:focus-visible {background-color:#065b1e; color:#fff; border-color:#065b1e;}
.btn2:focus-visible, .product-readmore:focus-visible {outline:3px solid #155eef !important; outline-offset:3px;}
@media (prefers-reduced-motion: reduce) {html {scroll-behavior:auto !important;} *, *::before, *::after {animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important;}}

