function saringtags(a,b){var c=a.replace(/<[^>]*>/g,"");return c.substring(0,b-1)}function relpostimgcuplik(d){for(var e=0;e<d.feed.entry.length;e++){var f=d.feed.entry[e];reljudul.push(f.title.$t);var g="";g=f.content?f.content.$t:f.summary?f.summary.$t:"",relcuplikan.push(saringtags(g,numchars));var h=defaultImage;f.media$thumbnail&&f.media$thumbnail.url&&(h=f.media$thumbnail.url);var i=g.match(/<img[^>]+src="([^">]+)"/);i&&i[1]&&(h=i[1]),relgambar.push(h);for(var j=0;j<f.link.length;j++)if(f.link[j].rel=="alternate"){relurls.push(f.link[j].href);break}}}function contains(a,b){for(var c=0;c<a.length;c++)if(a[c]===b)return!0;return!1}function artikelterkait(){for(var a=[],b=[],c=[],d=[],e=0;e<relurls.length;e++)!contains(a,relurls[e])&&relurls[e]!==document.URL&&(a.push(relurls[e]),b.push(reljudul[e]),c.push(relcuplikan[e]),d.push(relgambar[e]));if(0===a.length){document.write("<li>Tidak ada artikel lain</li>");return}for(var f=a.length-1;f>0;f--){var g=Math.floor(Math.random()*(f+1));[a[f],a[g]]=[a[g],a[f]],[b[f],b[g]]=[b[g],b[f]],[c[f],c[g]]=[c[g],c[f]],[d[f],d[g]]=[d[g],d[f]]}for(var h=Math.min(relmaxtampil,a.length),i=0;i<h;i++){var j="<img src='"+d[i]+"' onerror=\"this.src='"+defaultImage+"'\"/>",k="<li class='news-title clearfix'><a href='"+a[i]+"' rel='nofollow' target='_top' title='"+b[i]+"'>"+j+"</a><a class='relinkjdulx' href='"+a[i]+"' target='_top'>"+b[i]+"</a><span class='news-text'>"+(c[i]||"Baca selengkapnya...")+"</span></li>";document.write(k)}};
